.btn-danger { background: #fee2e2; color: var(--danger); }
.btn-ghost { background: transparent; border: 1px solid var(--line); }

.table-wrap { overflow: auto; border: 1px solid var(--line); border-radius: 12px; }
table { width: 100%; border-collapse: collapse; font-size: 13px; }
th, td { padding: 10px 12px; border-bottom: 1px solid var(--line); text-align: left; vertical-align: top; }
th { background: #f8fafc; color: var(--muted); font-weight: 600; white-space: nowrap; }
tr:last-child td { border-bottom: none; }

.badge {
  display: inline-flex; align-items: center;
  border-radius: 999px; padding: 2px 8px; font-size: 12px; font-weight: 600;
}
.badge.open { background: #dbeafe; color: #1d4ed8; }
.badge.in_progress { background: #ffedd5; color: var(--warn); }
.badge.resolved { background: #d1fae5; color: var(--ok); }
.badge.cancelled { background: #e5e7eb; color: #4b5563; }

.login-wrap {
  min-height: 100vh; display: grid; place-items: center; padding: 24px;
}
.login-card { width: min(420px, 100%); }
.login-card h1 { margin: 0 0 6px; font-size: 22px; }
.login-card .sub { color: var(--muted); margin-bottom: 18px; font-size: 13px; }
.stack { display: grid; gap: 12px; }
.error {
  background: #fef2f2; color: var(--danger); border: 1px solid #fecaca;
  border-radius: 10px; padding: 10px 12px; font-size: 13px;
}
.muted { color: var(--muted); font-size: 12px; }
.actions { display: flex; gap: 8px; flex-wrap: wrap; }
.mono { font-family: ui-monospace, Consolas, monospace; font-size: 12px; }
.drawer-mask {
  position: fixed; inset: 0; background: rgba(15, 23, 42, 0.35);
  display: grid; place-items: end center; padding: 24px;
}
.drawer {
  width: min(520px, 100%); background: #fff; border-radius: 16px;
  padding: 18px; box-shadow: var(--shadow);
}
@media (max-width: 900px) {
  .grid-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

input.command:
$root = "E:\project\清泉跨境系统（企业级）"
if (-not (Test-Path "$root\.env")) { Copy-Item "$root\.env.example" "$root\.env" }
$backend = "$root\backend"
$venv = "$backend\.venv"
$py = "$venv\Scripts\python.exe"
if (-not (Test-Path $py)) {
  python -m venv $venv
}
& $py -m pip install -q -r "$backend\requirements.txt"
Write-Host "pip done"

$bin = "C:\Program Files\PostgreSQL\16\bin"
if (-not (Test-Path "$bin\psql.exe")) { $bin = "C:\PostgreSQL\16\bin" }
$env:PGPASSWORD = "postgres"
Write-Host "using $bin"

# 修好 qingquan 密码与表权限
& "$bin\psql.exe" -h 127.0.0.1 -U postgres -d qingquan -v ON_ERROR_STOP=1 -c @"
DO `$`$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'qingquan') THEN
    CREATE ROLE qingquan LOGIN PASSWORD 'qingquan';
  ELSE
    ALTER ROLE qingquan WITH LOGIN PASSWORD 'qingquan';
  END IF;
END
`$`$;
GRANT ALL PRIVILEGES ON DATABASE qingquan TO qingquan;
GRANT ALL ON SCHEMA public TO qingquan;
GRANT ALL PRIVILEGES ON ALL TABLES IN SCHEMA public TO qingquan;
GRANT ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA public TO qingquan;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO qingquan;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON SEQUENCES TO qingquan;
"@ 2>&1

$env:PGPASSWORD = "qingquan"
& "$bin\psql.exe" -h 127.0.0.1 -U qingquan -d qingquan -c "SELECT current_user, COUNT(*) AS n FROM information_schema.tables WHERE table_schema='public';" 2>&1

# 启动 Vue
$web = 'E:\project\清泉跨境系统（企业级）\web'
Get-NetTCPConnection -LocalPort 5173 -ErrorAction SilentlyContinue | ForEach-Object {
  try { Stop-Process -Id $_.OwningProcess -Force -ErrorAction SilentlyContinue } catch {}
}
$logs = 'E:\project\清泉跨境系统（企业级）\logs'
$out = Join-Path $logs 'web.out.log'
$err = Join-Path $logs 'web.err.log'
$npm = (Get-Command npm).Source
$webProc = Start-Process -FilePath $npm -ArgumentList 'run','dev','--','--host','127.0.0.1','--port','5173' -WorkingDirectory $web -PassThru -RedirectStandardOutput $out -RedirectStandardError $err -WindowStyle Hidden
Write-Host "WEB PID=$($webProc.Id)"
$ready = $false
for ($i=0; $i -lt 40; $i++) {
  Start-Sleep -Seconds 1
  try {
    $r = Invoke-WebRequest -Uri 'http://127.0.0.1:5173/' -UseBasicParsing -TimeoutSec 2
    if ($r.StatusCode -eq 200) { $ready = $true; Write-Host "web OK status=$($r.StatusCode)"; break }
  } catch {}
}
if (-not $ready) {
  Write-Host 'web not ready'
  if (Test-Path -LiteralPath $err) { Get-Content -LiteralPath $err -Tail 40 }
  if (Test-Path -LiteralPath $out) { Get-Content -LiteralPath $out -Tail 40 }
} else {
  Get-Content -LiteralPath $out -Tail 15 -ErrorAction SilentlyContinue
}

# 经代理测 API
try {
  $h = Invoke-RestMethod -Uri 'http://127.0.0.1:5173/health' -TimeoutSec 3
  Write-Host "proxy health=$($h.status)"
} catch {
  Write-Host "proxy health fail: $_"
}

$web = 'E:\project\清泉跨境系统（企业级）\web'
$logs = 'E:\project\清泉跨境系统（企业级）\logs'
New-Item -ItemType Directory -Force -Path $logs | Out-Null
Get-NetTCPConnection -LocalPort 5173 -ErrorAction SilentlyContinue | ForEach-Object {
  try { Stop-Process -Id $_.OwningProcess -Force -ErrorAction SilentlyContinue } catch {}
}
$out = Join-Path $logs 'web.out.log'
$err = Join-Path $logs 'web.err.log'
$webProc = Start-Process -FilePath 'cmd.exe' -ArgumentList '/c','npm run dev -- --host 127.0.0.1 --port 5173' -WorkingDirectory $web -PassThru -RedirectStandardOutput $out -RedirectStandardError $err -WindowStyle Hidden
Write-Host "WEB PID=$($webProc.Id)"
$ready = $false
for ($i=0; $i -lt 45; $i++) {
  Start-Sleep -Seconds 1
  try {
    $r = Invoke-WebRequest -Uri 'http://127.0.0.1:5173/' -UseBasicParsing -TimeoutSec 2
    if ($r.StatusCode -eq 200) { $ready = $true; Write-Host "web OK"; break }
  } catch {}
}
if (-not $ready) {
  Write-Host 'web not ready'
  Get-Content -LiteralPath $err -Tail 40 -ErrorAction SilentlyContinue
  Get-Content -LiteralPath $out -Tail 40 -ErrorAction SilentlyContinue
} else {
  Get-Content -LiteralPath $out -Tail 20 -ErrorAction SilentlyContinue
  try {
    $h = Invoke-RestMethod -Uri 'http://127.0.0.1:5173/health' -TimeoutSec 3
    Write-Host "proxy health=$($h.status)"
  } catch { Write-Host "proxy health fail: $_" }
  # login via proxy
  $login = Invoke-RestMethod -Method Post -Uri 'http://127.0.0.1:5173/api/v1/auth/login' -ContentType 'application/json' -Body '{"username":"admin","password":"admin123"}'
  Write-Host "proxy login token_len=$($login.access_token.Length)"
}

Write-Host "=== Port 5432 listeners ==="
$conns = Get-NetTCPConnection -LocalPort 5432 -State Listen -ErrorAction SilentlyContinue
$conns | Select-Object LocalAddress, State, OwningProcess | Format-Table -AutoSize
$pids = $conns | Select-Object -ExpandProperty OwningProcess -Unique
foreach ($pid in $pids) {
  $p = Get-Process -Id $pid -ErrorAction SilentlyContinue
  if ($p) {
    Write-Host "PID $pid : $($p.ProcessName)"
    try {
      $path = (Get-CimInstance Win32_Process -Filter "ProcessId=$pid").ExecutablePath
      Write-Host "  Path: $path"
      $cmd = (Get-CimInstance Win32_Process -Filter "ProcessId=$pid").CommandLine
      Write-Host "  Cmd: $cmd"
    } catch {}
  }
}

Write-Host "`n=== Services ==="
Get-Service | Where-Object { $_.Name -match 'postgres|postgresql' -or $_.DisplayName -match 'PostgreSQL' } |
  Format-Table Name, Status, StartType, DisplayName -AutoSize

Write-Host "`n=== Install dirs ==="
@(
  'C:\Program Files\PostgreSQL\16',
  'C:\PostgreSQL\16',
  'C:\qingquan-pgdata',
  'C:\Program Files\PostgreSQL\16\data'
) | ForEach-Object {
  $exists = Test-Path $_
  $pgver = $null
  if (Test-Path (Join-Path $_ 'PG_VERSION')) { $pgver = Get-Content (Join-Path $_ 'PG_VERSION') -Raw }
  if (Test-Path (Join-Path $_ 'data\PG_VERSION')) { $pgver = Get-Content (Join-Path $_ 'data\PG_VERSION') -Raw }
  $libCount = 0
  if (Test-Path (Join-Path $_ 'lib')) { $libCount = (Get-ChildItem (Join-Path $_ 'lib') -ErrorAction SilentlyContinue | Measure-Object).Count }
  Write-Host ("{0} exists={1} PG_VERSION={2} lib_files={3}" -f $_, $exists, ($pgver -replace '\s',''), $libCount)
}

Write-Host "`n=== Connect tests ==="
$env:PGPASSWORD = 'postgres'
# try both bins
foreach ($bin in @('C:\Program Files\PostgreSQL\16\bin','C:\PostgreSQL\16\bin')) {
  $psql = Join-Path $bin 'psql.exe'
  if (-not (Test-Path $psql)) { Write-Host "missing $psql"; continue }
  Write-Host "--- $bin ---"
  try {
    $v = & $psql -h 127.0.0.1 -U postgres -d postgres -tAc "SELECT version();" 2>&1
    Write-Host "postgres super: $v"
  } catch { Write-Host "postgres super FAIL: $_" }
}

$env:PGPASSWORD = 'qingquan'
& 'C:\Program Files\PostgreSQL\16\bin\psql.exe' -h 127.0.0.1 -U qingquan -d qingquan -tAc "SELECT current_database(), current_user, COUNT(*) FROM information_schema.tables WHERE table_schema='public';" 2>&1

Write-Host "`n=== Data dir of running instance (SHOW data_directory) ==="
$env:PGPASSWORD = 'postgres'
& 'C:\Program Files\PostgreSQL\16\bin\psql.exe' -h 127.0.0.1 -U postgres -d postgres -tAc "SHOW data_directory; SHOW port; SHOW config_file;" 2>&1

Write-Host "`n=== Uninstall entries ==="
Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall','HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall' -ErrorAction SilentlyContinue |
  ForEach-Object {
    $p = Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue
    if ($p.DisplayName -match 'PostgreSQL') {
      [pscustomobject]@{ Name=$p.DisplayName; Version=$p.DisplayVersion; Uninstall=$p.UninstallString; InstallLocation=$p.InstallLocation }
    }
  } | Format-List

$ErrorActionPreference = 'Stop'
$bin = 'C:\Program Files\PostgreSQL\16\bin'
$backupDir = 'E:\backup'
New-Item -ItemType Directory -Force -Path $backupDir | Out-Null
$dump = Join-Path $backupDir ("qingquan-{0:yyyyMMdd-HHmmss}.dump" -f (Get-Date))

Write-Host "=== 1) Backup qingquan ===" -ForegroundColor Cyan
$env:PGPASSWORD = 'qingquan'
& "$bin\pg_dump.exe" -h 127.0.0.1 -U qingquan -d qingquan -F c -f $dump
if ($LASTEXITCODE -ne 0) { throw "pg_dump failed: $LASTEXITCODE" }
$dumpInfo = Get-Item $dump
Write-Host "backup OK: $($dumpInfo.FullName) size=$($dumpInfo.Length) bytes"

Write-Host "`n=== 2) Pre-check running instance ===" -ForegroundColor Cyan
$env:PGPASSWORD = 'postgres'
$before = & "$bin\psql.exe" -h 127.0.0.1 -U postgres -d postgres -tAc "SHOW data_directory;"
Write-Host "data_directory=$before"
$env:PGPASSWORD = 'qingquan'
$tblBefore = & "$bin\psql.exe" -h 127.0.0.1 -U qingquan -d qingquan -tAc "SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='public';"
Write-Host "qingquan public tables=$tblBefore"

Write-Host "`n=== 3) Stop/delete service postgresql-qq-16 ===" -ForegroundColor Cyan
$svc = Get-Service -Name 'postgresql-qq-16' -ErrorAction SilentlyContinue
if ($svc) {
  if ($svc.Status -ne 'Stopped') {
    Stop-Service -Name 'postgresql-qq-16' -Force -ErrorAction SilentlyContinue
    Start-Sleep -Seconds 2
  }
  # sc delete
  $del = sc.exe delete postgresql-qq-16 2>&1
  Write-Host "sc delete: $del"
  Start-Sleep -Seconds 1
  $svc2 = Get-Service -Name 'postgresql-qq-16' -ErrorAction SilentlyContinue
  if ($svc2) { Write-Warning "service still present: $($svc2.Status)" } else { Write-Host "service removed" }
} else {
  Write-Host "service already absent"
}

Write-Host "`n=== 4) Remove unused directories ===" -ForegroundColor Cyan
foreach ($path in @('C:\PostgreSQL\16', 'C:\qingquan-pgdata')) {
  if (Test-Path -LiteralPath $path) {
    Write-Host "removing $path ..."
    # take ownership/clear read-only if needed
    cmd /c "attrib -R `"$path\*.*`" /S /D" 2>$null | Out-Null
    Remove-Item -LiteralPath $path -Recurse -Force -ErrorAction Stop
    Write-Host "removed $path"
  } else {
    Write-Host "skip missing $path"
  }
}
# parent C:\PostgreSQL if empty
if ((Test-Path 'C:\PostgreSQL') -and -not (Get-ChildItem 'C:\PostgreSQL' -Force -ErrorAction SilentlyContinue)) {
  Remove-Item 'C:\PostgreSQL' -Force -ErrorAction SilentlyContinue
  Write-Host "removed empty C:\PostgreSQL"
}

Write-Host "`n=== 5) Post-check ===" -ForegroundColor Cyan
Write-Host "dirs:"
@('C:\Program Files\PostgreSQL\16','C:\PostgreSQL\16','C:\qingquan-pgdata','C:\Program Files\PostgreSQL\16\data') | ForEach-Object {
  Write-Host ("  {0} exists={1}" -f $_, (Test-Path -LiteralPath $_))
}

Write-Host "services:"
Get-Service | Where-Object { $_.Name -match 'postgres' -or $_.DisplayName -match 'PostgreSQL' } |
  Format-Table Name, Status, StartType -AutoSize | Out-String | Write-Host

Write-Host "port 5432:"
Get-NetTCPConnection -LocalPort 5432 -State Listen -ErrorAction SilentlyContinue |
  ForEach-Object {
    $proc = Get-CimInstance Win32_Process -Filter "ProcessId=$($_.OwningProcess)" -ErrorAction SilentlyContinue
    Write-Host ("  PID={0} Path={1}" -f $_.OwningProcess, $proc.ExecutablePath)
  }

$env:PGPASSWORD = 'postgres'
$after = & "$bin\psql.exe" -h 127.0.0.1 -U postgres -d postgres -tAc "SHOW data_directory; SELECT version();"
Write-Host "running:`n$after"

$env:PGPASSWORD = 'qingquan'
$tblAfter = & "$bin\psql.exe" -h 127.0.0.1 -U qingquan -d qingquan -c "SELECT COUNT(*) AS tables FROM information_schema.tables WHERE table_schema='public'; SELECT campaign_name, spend FROM fact_ads_campaign_daily; SELECT id::text, status, progress_note FROM task;"
Write-Host $tblAfter

# health if API still up
try {
  $h = Invoke-RestMethod -Uri 'http://127.0.0.1:8000/health' -TimeoutSec 3
  Write-Host "API health=$($h.status)"
} catch {
  Write-Host "API not running (ok if stopped): $_"
}

Write-Host "`n=== CLEANUP DONE ===" -ForegroundColor Green
Write-Host "backup: $dump"

$ErrorActionPreference = 'Stop'
$bin = 'C:\Program Files\PostgreSQL\16\bin'
$backupDir = 'E:\backup'
New-Item -ItemType Directory -Force -Path $backupDir | Out-Null
$dump = Join-Path $backupDir ("qingquan-{0:yyyyMMdd-HHmmss}.dump" -f (Get-Date))

Write-Host "=== 1) Backup qingquan ===" -ForegroundColor Cyan
$env:PGPASSWORD = 'qingquan'
& "$bin\pg_dump.exe" -h 127.0.0.1 -U qingquan -d qingquan -F c -f $dump
if ($LASTEXITCODE -ne 0) { throw "pg_dump failed: $LASTEXITCODE" }
$dumpInfo = Get-Item $dump
Write-Host "backup OK: $($dumpInfo.FullName) size=$($dumpInfo.Length)"

Write-Host "`n=== 2) Pre-check ===" -ForegroundColor Cyan
$env:PGPASSWORD = 'postgres'
Write-Host ("data_directory=" + (& "$bin\psql.exe" -h 127.0.0.1 -U postgres -d postgres -tAc "SHOW data_directory;"))
$env:PGPASSWORD = 'qingquan'
Write-Host ("tables=" + (& "$bin\psql.exe" -h 127.0.0.1 -U qingquan -d qingquan -tAc "SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='public';"))

Write-Host "`n=== 3) Stop/delete service postgresql-qq-16 ===" -ForegroundColor Cyan
$svc = Get-Service -Name 'postgresql-qq-16' -ErrorAction SilentlyContinue
if ($svc) {
  if ($svc.Status -ne 'Stopped') { Stop-Service -Name 'postgresql-qq-16' -Force -ErrorAction SilentlyContinue; Start-Sleep -Seconds 2 }
  $del = sc.exe delete postgresql-qq-16 2>&1
  Write-Host "sc delete: $del"
  Start-Sleep -Seconds 1
  if (Get-Service -Name 'postgresql-qq-16' -ErrorAction SilentlyContinue) { Write-Warning 'service still present' } else { Write-Host 'service removed' }
} else { Write-Host 'service already absent' }

Write-Host "`n=== 4) Remove unused dirs via cmd rmdir ===" -ForegroundColor Cyan
foreach ($path in @('C:\PostgreSQL\16', 'C:\qingquan-pgdata', 'C:\PostgreSQL')) {
  if (Test-Path -LiteralPath $path) {
    Write-Host "removing $path ..."
    # clear attributes
    cmd /c "attrib -R `"$path\*`" /S /D" | Out-Null
    $out = cmd /c "rmdir /s /q `"$path`"" 2>&1
    if ($out) { Write-Host $out }
    if (Test-Path -LiteralPath $path) {
      Write-Warning "still exists: $path — trying takeown/icacls"
      cmd /c "takeown /f `"$path`" /r /d y" | Out-Null
      cmd /c "icacls `"$path`" /grant Administrators:F /t" | Out-Null
      cmd /c "rmdir /s /q `"$path`"" 2>&1 | Write-Host
    }
    Write-Host ("exists after=" + (Test-Path -LiteralPath $path))
  } else {
    Write-Host "skip missing $path"
  }
}

Write-Host "`n=== 5) Post-check ===" -ForegroundColor Cyan
@('C:\Program Files\PostgreSQL\16','C:\PostgreSQL\16','C:\qingquan-pgdata','C:\Program Files\PostgreSQL\16\data','C:\PostgreSQL') | ForEach-Object {
  Write-Host ("  {0} exists={1}" -f $_, (Test-Path -LiteralPath $_))
}
Write-Host 'services:'
Get-Service | Where-Object { $_.Name -match 'postgres' -or $_.DisplayName -match 'PostgreSQL' } | Format-Table Name, Status, StartType -AutoSize | Out-String | Write-Host
Write-Host 'port 5432:'
Get-NetTCPConnection -LocalPort 5432 -State Listen -ErrorAction SilentlyContinue | ForEach-Object {
  $proc = Get-CimInstance Win32_Process -Filter "ProcessId=$($_.OwningProcess)" -ErrorAction SilentlyContinue
  Write-Host ("  PID={0} Path={1}" -f $_.OwningProcess, $proc.ExecutablePath)
}
$env:PGPASSWORD = 'postgres'
Write-Host ("data_directory=" + (& "$bin\psql.exe" -h 127.0.0.1 -U postgres -d postgres -tAc "SHOW data_directory;"))
$env:PGPASSWORD = 'qingquan'
& "$bin\psql.exe" -h 127.0.0.1 -U qingquan -d qingquan -c "SELECT COUNT(*) AS tables FROM information_schema.tables WHERE table_schema='public'; SELECT campaign_name, spend FROM fact_ads_campaign_daily; SELECT left(id::text,8) AS id8, status, progress_note FROM task;"
try { Write-Host ("API health=" + (Invoke-RestMethod http://127.0.0.1:8000/health -TimeoutSec 3).status) } catch { Write-Host 'API offline (optional)' }
Write-Host "`nDONE backup=$dump" -ForegroundColor Green
